do $$
declare tenant uuid:=gen_random_uuid();other_tenant uuid:=gen_random_uuid();admin_user uuid:=gen_random_uuid();school_user uuid:=gen_random_uuid();school uuid:=gen_random_uuid();other_school uuid:=gen_random_uuid();ev uuid:=gen_random_uuid();sport uuid:=gen_random_uuid();cat1 uuid:=gen_random_uuid();cat2 uuid:=gen_random_uuid();athlete uuid:=gen_random_uuid();professional uuid:=gen_random_uuid();role_id uuid:=gen_random_uuid();part uuid;r1 uuid;r2 uuid;result jsonb;detail jsonb;fingerprint text;old_fingerprint text;denied boolean;saved_review_id uuid;
begin
 begin
 insert into auth.users(id) values(admin_user),(school_user);
 insert into public.institutions(id,name,slug) values(tenant,'Conferência técnica','staff-review-'||tenant),(other_tenant,'Outro','staff-review-'||other_tenant);
 insert into public.institution_memberships(institution_id,user_id,role,status) values(tenant,admin_user,'admin','approved');
 insert into public.schools(id,institution_id,name) values(school,tenant,'Escola'),(other_school,tenant,'Outra escola');
 insert into public.events(id,institution_id,name,status) values(ev,tenant,'Evento','open');
 insert into public.event_modalities(id,institution_id,event_id,name,classification) values(sport,tenant,ev,'Atletismo','individual');
 insert into public.event_categories(id,institution_id,event_id,modality_id,name,participation) values(cat1,tenant,ev,sport,'Categoria 1','individual'),(cat2,tenant,ev,sport,'Categoria 2','individual');
 insert into public.event_staff_roles(id,institution_id,event_id,name) values(role_id,tenant,ev,'Técnico');
 insert into public.people(id,institution_id,full_name,birth_date,cpf,gender) values(athlete,tenant,'Atleta','2010-01-01','52998224725','Feminino'),(professional,tenant,'Profissional','1990-01-01','11144477735','Feminino');
 insert into public.school_people(institution_id,school_id,person_id,role,status,user_id) values(tenant,school,athlete,'athlete','approved',null),(tenant,school,professional,'staff','approved',null),(tenant,school,professional,'responsible','approved',school_user);
 perform set_config('request.jwt.claim.sub',school_user::text,true);execute 'set local role authenticated';
 result:=public.siep_save_participation(ev,school,athlete,array[cat1,cat2],'{}',true);part:=(result->>'id')::uuid;
 result:=public.siep_save_registration(ev,school,cat1,null,jsonb_build_array(jsonb_build_object('participation_id',part,'slot_number',1)),jsonb_build_array(jsonb_build_object('person_id',professional,'staff_role_id',role_id)));r1:=(result->>'id')::uuid;
 result:=public.siep_save_registration(ev,school,cat2,null,jsonb_build_array(jsonb_build_object('participation_id',part,'slot_number',1)),jsonb_build_array(jsonb_build_object('person_id',professional,'staff_role_id',role_id)));r2:=(result->>'id')::uuid;
 result:=public.siep_staff_conference_page(tenant,school);if (result->>'total')::int<>1 or (result#>>'{rows,0,registration_count}')::int<>2 then raise exception 'Profissional repetido por modalidade: %',result;end if;
 detail:=public.siep_staff_conference_detail(tenant,ev,school,professional);fingerprint:=detail->>'fingerprint';
 denied:=false;begin perform public.siep_review_staff(tenant,ev,school,professional,0,fingerprint,'approved','Conferido');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Escola decidiu conferência';end if;
 denied:=false;begin perform public.siep_staff_conference_detail(tenant,ev,other_school,professional);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Escola consultou outra escola';end if;
 denied:=false;begin perform public.siep_staff_conference_page(other_tenant,school);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Consulta atravessou instituição';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',admin_user::text,true);execute 'set local role authenticated';
 result:=public.siep_review_staff(tenant,ev,school,professional,0,fingerprint,'approved','Cadastro conferido');
 if result->>'status'<>'approved' then raise exception 'Aprovação não persistiu';end if;
 denied:=false;begin perform public.siep_review_staff(tenant,ev,school,professional,0,fingerprint,'rejected','Concorrente');exception when serialization_failure then denied:=true;end;if not denied then raise exception 'Revisão concorrente aceita';end if;
 execute 'reset role';
 if exists(select 1 from public.registrations where id in(r1,r2) and status<>'draft') then raise exception 'Decisão de profissional alterou atletas';end if;
 delete from public.registration_staff where registration_id=r2;
 detail:=siep_private.staff_conference_row(tenant,ev,school,professional);if detail->>'status'<>'approved' or (detail->>'registration_count')::int<>1 then raise exception 'Vínculo na mesma função exigiu análise duplicada';end if;
 old_fingerprint:=fingerprint;
 update public.people set full_name='Profissional atualizado' where id=professional;
 detail:=siep_private.staff_conference_row(tenant,ev,school,professional);if detail->>'status'<>'pending' or (detail->>'outdated')::boolean is not true then raise exception 'Cadastro alterado preservou aprovação';end if;
 fingerprint:=detail->>'fingerprint';
 execute 'set local role authenticated';
 denied:=false;begin perform public.siep_review_staff(tenant,ev,school,professional,1,old_fingerprint,'approved','Desatualizado');exception when serialization_failure then denied:=true;end;if not denied then raise exception 'Snapshot desatualizado aceito';end if;
 denied:=false;begin perform public.siep_review_staff(tenant,ev,school,professional,1,fingerprint,'approved',' ');exception when check_violation then denied:=true;end;if not denied then raise exception 'Justificativa vazia aceita';end if;
 result:=public.siep_review_staff(tenant,ev,school,professional,1,fingerprint,'correction_requested','Atualizar foto');execute 'reset role';
 select id into saved_review_id from public.staff_event_reviews where institution_id=tenant;
 if not exists(select 1 from public.staff_event_review_history where review_id=saved_review_id and revision=1 and snapshot#>>'{person,full_name}'='Profissional') then raise exception 'Histórico perdeu snapshot anterior';end if;
 perform set_config('request.jwt.claim.sub',school_user::text,true);execute 'set local role authenticated';
 detail:=public.siep_staff_conference_detail(tenant,ev,school,professional);if detail->>'status'<>'correction_requested' or detail->>'last_reason'<>'Atualizar foto' or jsonb_array_length(detail->'history')<>2 then raise exception 'Escola não consultou orientação/histórico';end if;
 execute 'reset role';
 if not exists(select 1 from public.notifications where institution_id=tenant and recipient_user_id=school_user and kind='staff_review' and payload->>'person_id'=professional::text and payload->>'status'='correction_requested') then raise exception 'Aviso de correção técnica não chegou ao responsável';end if;
 denied:=false;begin delete from public.staff_event_review_history where review_id=saved_review_id;exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Histórico apagado';end if;
 if has_function_privilege('anon','public.siep_review_staff(uuid,uuid,uuid,uuid,integer,text,text,text)','execute') or has_table_privilege('authenticated','public.staff_event_reviews','update') then raise exception 'Permissão excessiva';end if;
 raise exception 'rollback_staff_conference' using errcode='ZX001';
 exception when sqlstate 'ZX001' then null;
 end;
end $$;
